    local container = CreateFrame("Frame", nil, parent, "BackdropTemplate")
    local font = container:CreateFontString(nil, "OVERLAY", textTemplate)
    local useLeadingDash = (showLeadingDash ~= false)
    font:SetWordWrap(true)
    font:SetWidth(width - 5)
    font:SetPoint("TOPLEFT", 5, -5)
    font:SetText((useLeadingDash and "- " or "") .. text)
    font:SetJustifyH("LEFT")

    container:SetWidth(width)
    container:SetHeight(font:GetStringHeight() + 10)

    -- EllesmereUI's tracker uses gold for quest/title lines, the live accent
    -- for section headers, and gray for objective text. "warning" maps to the
    -- same gold in APR's native palette, so this also preserves the default UI.
    local role = color and self:ResolveTextColorRole(color, "title") or (isExtraLine and "title" or "base")
    self:RegisterFontString(font, textScope or "general", {
        role = role,
        onApplied = --[[APR_DIAG]]APRTrace("APR-Core/utils/UIUtils.lua:637:callback#36", --[[/APR_DIAG]]function(fontString)
            container:SetHeight(container.progressBarOnly and 30 or
                (fontString:GetStringHeight() + 10 + (container.extraContentHeight or 0)))
        end--[[APR_DIAG]])--[[/APR_DIAG]],
    })

    if backdropColor then
        container:SetBackdrop({
            bgFile = "Interface\\BUTTONS\\WHITE8X8",
            tile = true,
            tileSize = 16
        })
        APR:SetPanelColor(container, backdropColor)
    else
        container:SetBackdrop(nil)
    end

    container.font = font
    if self.RegisterSkinTarget then self:RegisterSkinTarget(container, "row") end
    container.showLeadingDash = useLeadingDash
    return container
end--[[APR_DIAG]]; APR.CreateStepTextContainer = APRTrace("APR-Core/utils/UIUtils.lua:617:APR:CreateStepTextContainer#35", APR.CreateStepTextContainer)--[[/APR_DIAG]]

--- Snap a frame to an anchor frame at a calculated distance.
-- Centralizes the snap positioning logic used by multiple modules (FillersFrame, QuestOrderList, AFK).
-- Handles ClearAllPoints + SetPoint with proper offset calculation and scale synchronization.
---@param frame table The frame to position
---@param anchorFrame table The reference frame to snap to
---@param anchorHeight number The effective height of anchor frame (used for offset calculation)
---@param gap number The gap between anchor and frame (positive = below, negative = above)
---@param adjustForHeader number|nil Optional header height to add to offset (e.g., 20 for standard header)
---@return boolean True if successfully snapped, false if anchor is invalid
function APR:SnapFrameToAnchor(frame, anchorFrame, anchorHeight, gap, adjustForHeader)
    if not frame or not anchorFrame then
        return false
    end
    if self.SetFrameSnapAnchor then self:SetFrameSnapAnchor(frame, anchorFrame) end
    frame:SetClampedToScreen(false)

    -- Synchronize scale with anchor
    local anchorScale = anchorFrame:GetScale() or 1
    if frame:GetScale() ~= anchorScale then
        frame:SetScale(anchorScale)
    end

    -- Calculate total offset
    local totalOffset = math.floor(anchorHeight + gap)
    if adjustForHeader and adjustForHeader > 0 then
        totalOffset = totalOffset + adjustForHeader
    end

    -- LibWindow can restore a saved point without changing size/scale. Compare the
    -- actual anchor, never just the last requested layout, before skipping a move.
    if frame.GetPoint then
        local point, relative, relativePoint, x, y = frame:GetPoint(1)
        if point == "TOP" and relative == anchorFrame and relativePoint == "TOP" and
            x == 0 and y == -totalOffset then return true end
    end
    frame:ClearAllPoints()
    frame:SetPoint("TOP", anchorFrame, "TOP", 0, -totalOffset)

    return true
end--[[APR_DIAG]]; APR.SnapFrameToAnchor = APRTrace("APR-Core/utils/UIUtils.lua:669:APR:SnapFrameToAnchor#37", APR.SnapFrameToAnchor)--[[/APR_DIAG]]

-- One chain definition is shared by runtime layout and the placement previews.
local function addSnappedFrame(stack, previews, frame, linked, visible, gap)
    if frame and linked and (previews or visible) then
        stack[#stack + 1] = {frame = frame, height = frame:GetHeight(), gap = gap}
    end
end--[[APR_DIAG]]; addSnappedFrame = APRTrace("APR-Core/utils/UIUtils.lua:702:addSnappedFrame#38", addSnappedFrame)--[[/APR_DIAG]]

function APR:GetSnappedStack(previews)
    local profile = self:GetSettingsProfile()
    local current = previews and previews[1] or _G.CurrentStepScreenPanel
    if not current or not profile then return {} end
    local height = previews and current:GetHeight() or self.currentStep:GetContentHeight(false)
    height = math.max(1, current.collapsed and current:GetHeight() or height or current:GetHeight())
    local stack = {{frame = current, height = height, gap = 0}}
    local afk = previews and previews[3] or _G.AfkFrameScreen
    local fillers = previews and previews[2] or _G.FillersScreenPanel
    local list = previews and previews[4] or _G.QuestOrderListPanel
    addSnappedFrame(stack, previews, afk, profile.afkSnapToCurrentStep, self:IsAFKFrameActiveShouldSnap(), 0)
    addSnappedFrame(stack, previews, fillers, profile.fillersFrameSnapToCurrentStep, not current.collapsed and fillers and fillers:IsShown(),
        (profile.fillersFrameSnapGap or 0) + (profile.fillersFrameShowHeader and 22 or 0))
    addSnappedFrame(stack, previews, list, profile.questOrderListSnapToCurrentStep, not current.collapsed and list and list:IsShown(), 30)
    return stack
end--[[APR_DIAG]]; APR.GetSnappedStack = APRTrace("APR-Core/utils/UIUtils.lua:708:APR:GetSnappedStack#39", APR.GetSnappedStack)--[[/APR_DIAG]]

function APR:GetSnappedStackHeight(previews)
    local stack, height = self:GetSnappedStack(previews), 0
    for i, entry in ipairs(stack) do
        if i > 1 then height = height - stack[i - 1].height + math.floor(stack[i - 1].height + entry.gap) end
        height = height + entry.height
    end
    return height
end--[[APR_DIAG]]; APR.GetSnappedStackHeight = APRTrace("APR-Core/utils/UIUtils.lua:725:APR:GetSnappedStackHeight#40", APR.GetSnappedStackHeight)--[[/APR_DIAG]]

function APR:RefreshSnappedFrames()
    if self.refreshingSnapChain or InCombatLockdown() then return end
    self.snappedLayoutRevision = (self.snappedLayoutRevision or 0) + 1
    self.refreshingSnapChain = true
    if self.AFK and self.AFK.RefreshFrameAnchor then self.AFK:RefreshFrameAnchor() end
    if self.fillersFrame and self.fillersFrame.RefreshFillersFrame and not self.fillersFrame.layoutDirty then
        self.fillersFrame:RefreshFillersFrame()
    end
    if self.questOrderList and self.questOrderList.ApplySnapAnchor then self.questOrderList:ApplySnapAnchor() end
    self.refreshingSnapChain = nil
end--[[APR_DIAG]]; APR.RefreshSnappedFrames = APRTrace("APR-Core/utils/UIUtils.lua:734:APR:RefreshSnappedFrames#41", APR.RefreshSnappedFrames)--[[/APR_DIAG]]

local reportedInvalidUIAssets = {}
local knownUIAssetCache = {}

--- Check a texture, font or other UI file without breaking clients before 12.0.7.
--- On clients without C_UIFileAsset, the asset is trusted and the caller keeps its legacy behavior.
---@param asset number|string|nil
---@return boolean isKnown
---@return boolean validationAvailable
function APR:IsUIFileAssetKnown(asset)
    if asset == nil or asset == "" then
        return false, C_UIFileAsset ~= nil and type(C_UIFileAsset.IsKnownFile) == "function"
    end

    if not C_UIFileAsset or type(C_UIFileAsset.IsKnownFile) ~= "function" then
        return true, false
    end

    if knownUIAssetCache[asset] ~= nil then
        return knownUIAssetCache[asset], true
    end

    local ok, isKnown = --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](C_UIFileAsset.IsKnownFile, asset)
    knownUIAssetCache[asset] = ok and isKnown == true
    return knownUIAssetCache[asset], true
end--[[APR_DIAG]]; APR.IsUIFileAssetKnown = APRTrace("APR-Core/utils/UIUtils.lua:754:APR:IsUIFileAssetKnown#42", APR.IsUIFileAssetKnown)--[[/APR_DIAG]]

--- Validate a UI file and optionally fall back to another one.
--- Invalid assets are reported once so a bad font or route image has an actionable failure mode.
---@param asset number|string|nil
---@param fallback number|string|nil
---@param context string|nil
---@return number|string|nil
function APR:ResolveUIFileAsset(asset, fallback, context)
    local isKnown, validationAvailable = self:IsUIFileAssetKnown(asset)
    if isKnown or not validationAvailable then
        return asset
    end

    local diagnosticKey = tostring(context or "UI") .. ":" .. tostring(asset)
    if not reportedInvalidUIAssets[diagnosticKey] then
        reportedInvalidUIAssets[diagnosticKey] = true
        local message = string.format("Unknown UI asset (%s): %s", context or "UI", tostring(asset))
        if self.PrintError then
            self:PrintError(message)
        else
            self:PrintInfo(message)
        end
    end

    if fallback ~= nil then
        local fallbackIsKnown, fallbackValidationAvailable = self:IsUIFileAssetKnown(fallback)
        if fallbackIsKnown or not fallbackValidationAvailable then
            return fallback
        end
    end

    return nil
end--[[APR_DIAG]]; APR.ResolveUIFileAsset = APRTrace("APR-Core/utils/UIUtils.lua:778:APR:ResolveUIFileAsset#43", APR.ResolveUIFileAsset)--[[/APR_DIAG]]

--- Validate the small set of files required for APR's main UI.
--- Route preview images and configured fonts are validated lazily when used.
function APR:ValidateBundledUIAssets()
    for context, asset in pairs({
        UI_ASSET_LOGO = "Interface\\AddOns\\APR\\APR-Core\\assets\\APR_logo.blp",
        UI_ASSET_CHANGELOG = "Interface\\AddOns\\APR\\APR-Core\\assets\\header.blp",
        UI_ASSET_MAP = "Interface\\AddOns\\APR\\APR-Core\\assets\\Icon.tga",
        UI_ASSET_ARROW = "Interface\\AddOns\\APR\\APR-Core\\assets\\Arrow.blp",
    }) do
        self:ResolveUIFileAsset(asset, nil, context)
    end
end--[[APR_DIAG]]; APR.ValidateBundledUIAssets = APRTrace("APR-Core/utils/UIUtils.lua:807:APR:ValidateBundledUIAssets#44", APR.ValidateBundledUIAssets)--[[/APR_DIAG]]
